const int maxn = 3005;
const int mod = 1e9 + 7;
int n;
vector<pair<int, int>> adj[maxn];
vector<int> dp[maxn];
int sz[maxn];
long long fact[maxn], invfact[maxn];
long long modpow(long long a, long long b) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % mod * invfact[n - k] % mod;
}

void dfs(int u, int p) {
    debug(u, p);
    sz[u] = 1;
    dp[u] = {0, 1};

    for(const auto &[v, w] : adj[u]) {
        if(v == p) continue;
        dfs(v, u);
        vector<long long> pref(sz[v] + 1, 0);
        for(int i = 1; i <= sz[v]; i++) {
            pref[i] = (pref[i - 1] + dp[v][i]) % mod;
        }
        vector<int> newdp(sz[u] + sz[v] + 1, 0);

        vector<long long> ways(sz[v] + 1, 0);
        for(int i = 0; i <= sz[v]; i++) {
            if(w == 1) {
                ways[i] = (pref[sz[v]] - pref[i] + mod) % mod;
            } else {
                ways[i] = pref[i];
            }
        }
        for(int i = 1; i <= sz[u]; i++) {
            if(dp[u][i] == 0) continue;
            for(int j = 0; j <= sz[v]; j++) {
                if(ways[j] == 0) continue;
                newdp[i + j] = (newdp[i + j] + dp[u][i] * ways[j] % mod * comb(i + j - 1, j) % mod * comb(sz[u] + sz[v] - i - j, sz[v] - j) % mod) % mod;
            }
        }
        sz[u] += sz[v];
        dp[u] = move(newdp);
    }
}

int main() {
    cin >> n;
    for(int i = 1; i < n; i++) {
        int u, v, w;
        cin >> u >> v;
        adj[u].emplace_back(v, 1);
        adj[v].emplace_back(u, -1);
    }
    fact[0] = 1;
    invfact[0] = 1;
    for(int i = 1; i < maxn; i++) {
        fact[i] = fact[i - 1] * i % mod;
        invfact[i] = modpow(fact[i], mod - 2);
    }
    dfs(1, 0);
    long long ans = 0;
    for(int i = 1; i <= n; i++) {
        ans = (ans + dp[1][i]) % mod;
    }
    cout << ans;
}